import React from 'react';
import { Play, Pause, RotateCcw, Activity, Shield, AlertTriangle, CheckCircle } from 'lucide-react';

const Dashboard = ({ isRunning, onStart, onStop, onReset, metrics }) => {
  const getHealthColor = (health) => {
    if (health >= 80) return '#10b981';
    if (health >= 50) return '#f59e0b';
    return '#ef4444';
  };

  const getHealthStatus = (health) => {
    if (health >= 80) return 'Optimal';
    if (health >= 50) return 'Degraded';
    return 'Critical';
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 p-6">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-white mb-2">Network Security Monitor</h1>
          <p className="text-slate-400">Real-time threat detection and system analytics</p>
        </div>

        {/* Control Panel */}
        <div className="bg-slate-800/50 backdrop-blur-sm rounded-2xl border border-slate-700 p-6 mb-6 shadow-2xl">
          <div className="flex flex-wrap items-center gap-4">
            <button
              className={`flex items-center gap-3 px-6 py-3 rounded-xl font-semibold transition-all duration-200 shadow-lg ${
                isRunning 
                  ? 'bg-red-500 hover:bg-red-600 text-white' 
                  : 'bg-gradient-to-r from-green-500 to-emerald-500 hover:from-green-600 hover:to-emerald-600 text-white'
              }`}
              onClick={isRunning ? onStop : onStart}
            >
              {isRunning ? (
                <>
                  <Pause size={20} />
                  <span>Stop Simulation</span>
                </>
              ) : (
                <>
                  <Play size={20} />
                  <span>Start Simulation</span>
                </>
              )}
            </button>

            <button 
              className="flex items-center gap-3 px-6 py-3 rounded-xl font-semibold bg-slate-700 hover:bg-slate-600 text-white transition-all duration-200 shadow-lg"
              onClick={onReset}
            >
              <RotateCcw size={20} />
              <span>Reset System</span>
            </button>

            <div className={`ml-auto flex items-center gap-3 px-5 py-3 rounded-xl font-semibold ${
              isRunning ? 'bg-green-500/20 text-green-400 border border-green-500/30' : 'bg-slate-700/50 text-slate-400 border border-slate-600'
            }`}>
              <Activity size={20} className={isRunning ? 'animate-pulse' : ''} />
              <span className="font-mono">{isRunning ? 'RUNNING' : 'STOPPED'}</span>
            </div>
          </div>
        </div>

        {/* Metrics Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {/* Total Packets Card */}
          <div className="bg-gradient-to-br from-blue-500/10 to-blue-600/10 backdrop-blur-sm rounded-2xl border border-blue-500/20 p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105">
            <div className="flex items-start justify-between mb-4">
              <div className="p-3 bg-blue-500/20 rounded-xl">
                <Activity size={28} className="text-blue-400" />
              </div>
            </div>
            <h3 className="text-slate-400 text-sm font-medium mb-2">Total Packets</h3>
            <p className="text-4xl font-bold text-white mb-1">{metrics.totalPackets.toLocaleString()}</p>
            <div className="flex items-center gap-2 mt-3">
              <div className="h-1.5 flex-1 bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-gradient-to-r from-blue-500 to-blue-400 rounded-full" style={{ width: '100%' }}></div>
              </div>
            </div>
          </div>

          {/* Blocked Packets Card */}
          <div className="bg-gradient-to-br from-red-500/10 to-red-600/10 backdrop-blur-sm rounded-2xl border border-red-500/20 p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105">
            <div className="flex items-start justify-between mb-4">
              <div className="p-3 bg-red-500/20 rounded-xl">
                <Shield size={28} className="text-red-400" />
              </div>
            </div>
            <h3 className="text-slate-400 text-sm font-medium mb-2">Blocked Packets</h3>
            <p className="text-4xl font-bold text-white mb-1">{metrics.blockedPackets.toLocaleString()}</p>
            <div className="flex items-center gap-2 mt-3">
              <div className="h-1.5 flex-1 bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-gradient-to-r from-red-500 to-red-400 rounded-full" 
                     style={{ width: `${Math.min((metrics.blockedPackets / metrics.totalPackets) * 100, 100)}%` }}></div>
              </div>
            </div>
          </div>

          {/* Attacks Detected Card */}
          <div className="bg-gradient-to-br from-amber-500/10 to-amber-600/10 backdrop-blur-sm rounded-2xl border border-amber-500/20 p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105">
            <div className="flex items-start justify-between mb-4">
              <div className="p-3 bg-amber-500/20 rounded-xl">
                <AlertTriangle size={28} className="text-amber-400" />
              </div>
            </div>
            <h3 className="text-slate-400 text-sm font-medium mb-2">Attacks Detected</h3>
            <p className="text-4xl font-bold text-white mb-1">{metrics.attacksDetected.toLocaleString()}</p>
            <div className="flex items-center gap-2 mt-3">
              <div className="h-1.5 flex-1 bg-slate-700 rounded-full overflow-hidden">
                <div className="h-full bg-gradient-to-r from-amber-500 to-amber-400 rounded-full" style={{ width: '75%' }}></div>
              </div>
            </div>
          </div>

          {/* System Health Card */}
          <div className={`bg-gradient-to-br backdrop-blur-sm rounded-2xl border p-6 shadow-xl hover:shadow-2xl transition-all duration-300 hover:scale-105 ${
            metrics.systemHealth >= 80 
              ? 'from-emerald-500/10 to-emerald-600/10 border-emerald-500/20' 
              : metrics.systemHealth >= 50 
              ? 'from-amber-500/10 to-amber-600/10 border-amber-500/20' 
              : 'from-red-500/10 to-red-600/10 border-red-500/20'
          }`}>
            <div className="flex items-start justify-between mb-4">
              <div className={`p-3 rounded-xl ${
                metrics.systemHealth >= 80 
                  ? 'bg-emerald-500/20' 
                  : metrics.systemHealth >= 50 
                  ? 'bg-amber-500/20' 
                  : 'bg-red-500/20'
              }`}>
                <CheckCircle size={28} style={{ color: getHealthColor(metrics.systemHealth) }} />
              </div>
            </div>
            <h3 className="text-slate-400 text-sm font-medium mb-2">System Health</h3>
            <p className="text-4xl font-bold mb-1" style={{ color: getHealthColor(metrics.systemHealth) }}>
              {metrics.systemHealth}%
            </p>
            <span className={`inline-block px-3 py-1 rounded-full text-xs font-semibold mt-2 ${
              metrics.systemHealth >= 80 
                ? 'bg-emerald-500/20 text-emerald-400' 
                : metrics.systemHealth >= 50 
                ? 'bg-amber-500/20 text-amber-400' 
                : 'bg-red-500/20 text-red-400'
            }`}>
              {getHealthStatus(metrics.systemHealth)}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
